def integer_nth_root(n, k):
    if n == 0:
        return 0
    r = 0
    while (r + 1) ** k <= n:
        r += 1
    return r

def stable_unique_preserve_order(items):
    seen = set()
    output = []
    for item in items:
        if item not in seen:
            output.append(item)
            seen.add(item)
    return output

def is_balanced_list(lst):
    n = len(lst)
    for i in range(n):
        if sum(lst[:i]) == sum(lst[i + 1:]):
            return True
    return False

