def classify_and_sort_by_parity(nums):
    evens = []
    odds = []
    for x in nums:
        if x % 2 == 0:
            evens.append(x)
        else:
            odds.append(x)
    evens.sort()
    odds.sort()
    return evens + odds

def count_local_maxima_including_endpoints(lst):
    n = len(lst)
    if n == 0:
        return 0
    if n == 1:
        return 1
    total = 0
    for i in range(n):
        left_ok = (i == 0) or (lst[i] > lst[i - 1])
        right_ok = (i == n - 1) or (lst[i] > lst[i + 1])
        if left_ok and right_ok:
            total += 1
    return total

def anagram_groups(words):
    groups = {}
    for word in words:
        key = ''.join(sorted(word))
        groups.setdefault(key, []).append(word)
    return {key: sorted(vals) for key, vals in groups.items()}

