def can_be_valid_with_wildcards(s):
    possible = {0}
    for c in s:
        next_possible = set()
        for bal in possible:
            if c == '(':
                next_possible.add(bal + 1)
            elif c == ')':
                if bal > 0:
                    next_possible.add(bal - 1)
            else:
                next_possible.add(bal + 1)
                if bal > 0:
                    next_possible.add(bal - 1)
                next_possible.add(bal)
        possible = next_possible
        if not possible:
            return False
    return 0 in possible

